package ca.yorku.eecs3311.coursepilot.web; import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import ca.yorku.eecs3311.coursepilot.application.service.RecommendationService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/courses/{courseId}/recommendation") public class RecommendationController {private final StudyAgentFacade facade;private final RecommendationService recommendations;public RecommendationController(StudyAgentFacade f,RecommendationService r){facade=f;recommendations=r;}@GetMapping public String page(@PathVariable Long courseId,Model m){m.addAttribute("course",facade.getCourse(courseId));m.addAttribute("recommendation",recommendations.recommend(courseId));m.addAttribute("activeNav","recommendation");return "recommendation/index";}}
